import React, { useState } from "react";
import "./JobForm.css";

const JobForm = ({ fetchJobs }) => {
  const [formData, setFormData] = useState({
    company: "",
    role: "",
    status: "Applied",
    date: "",
    link: "",
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const newJob = {
      company,
      role,
      status,
      date,
      link,
    };

    try {
      const response = await fetch("http://localhost:5000/api/jobs", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(newJob),
      });

      if (!response.ok) {
        throw new Error("Failed to add job");
      }

      const data = await response.json();
      onAdd(data); // callback to update the list
      setCompany("");
      setRole("");
      setStatus("Applied");
      setDate("");
      setLink("");
    } catch (error) {
      console.error("Error:", error);
    }
  };

  return (
    <form className="job-form" onSubmit={handleSubmit}>
      <input name="company" value={formData.company} onChange={handleChange} placeholder="Company" required />
      <input name="role" value={formData.role} onChange={handleChange} placeholder="Role" required />
      <select name="status" value={formData.status} onChange={handleChange}>
        <option>Applied</option>
        <option>Interview</option>
        <option>Offer</option>
        <option>Rejected</option>
      </select>
      <input name="date" type="date" value={formData.date} onChange={handleChange} required />
      <input name="link" value={formData.link} onChange={handleChange} placeholder="Job Link" required />
      <button type="submit">Add Job</button>
    </form>
  );
};

export default JobForm;
